programs.haiku:
"""Adverbs and connectives: a negative response to words that link or qualify clauses.

The component's activation is strongly negative on adverbs and conjunctions that sit
between or inside clauses ("therefore", "also", "but", "and", "then", "only", "not"),
and near zero on nouns, pronouns, determiners, prepositions and punctuation. The most
negative are sentence-linking adverbs (therefore, thus, however, also); -ly adverbs
(usually, particularly, recently) are strongly negative too, while -ly adjectives and
nouns (family, early, daily) are not. Discourse words in other languages (Russian и/но,
French mais, Japanese で/として) carry the same sign.

The program reads only the newest token and assigns each word class a fixed value.
"""

READS = ()

# Sentence-linking adverbs: the most negative group.
STRONG = {'therefore', 'thus', 'hence', 'however', 'furthermore', 'moreover', 'also', 'simply',
          'alternatively', 'instead', 'consequently', 'additionally', 'wait', 'hmm'}
# Time and focus particles and discourse particles.
FOCUS = {'then', 'now', 'still', 'already', 'only', 'just', 'often', 'always', 'even', 'so', 'well',
         'actually', 'rather', 'too', 'yet', 'usually', 'sometimes', 'particularly', 'probably',
         'perhaps', 'maybe', 'again', 'else', 'finally', 'never', 'than', 'especially', 'exactly',
         'really', 'indeed'}
# Coordinating and correlative conjunctions.
COORD = {'and', 'or', 'but', 'nor', 'either', 'both', 'while'}
# Negation and degree words: weakly negative.
DEGREE = {'not', 'very', 'more', 'most', 'much', 'less', 'here', 'why', 'many'}
# Connectives in other languages.
MULTI = {'и', 'но', 'или', 'mais', 'además', 'pero', 'также', 'und', 'aber', 'auch', 'で', 'に',
         'として', 'では', 'そして', 'しかし', 'поэтому', 'значит', 'donc', 'aussi', 'también'}
# -ly words that are not adverbs.
NOT_ADV = {'family', 'supply', 'apply', 'july', 'fly', 'rely', 'comply', 'friendly', 'lovely',
           'early', 'daily', 'weekly', 'monthly', 'nightly', 'assembly', 'italy', 'curly', 'ugly',
           'holy'}

# Mean activation per class, fit on sampled training rows.
VALUE = {'strong': -5.5, 'focus': -3.7, 'coord': -2.5, 'degree': -1.7, 'multi': -2.8, 'ly': -4.4}


def word_class(word):
    if word in STRONG:
        return 'strong'
    if word in FOCUS:
        return 'focus'
    if word in COORD:
        return 'coord'
    if word in DEGREE:
        return 'degree'
    if word in MULTI:
        return 'multi'
    if word.isalpha() and len(word) > 3 and word.endswith('ly') and word not in NOT_ADV:
        return 'ly'
    return None


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    cls = word_class(word)
    return carry, (VALUE[cls] if cls else 0.0)

"""Layer 15 MLP down_proj, component 2784: a subject-pronoun feature.

Almost everywhere this component sits near its resting value (about -0.1).
Its large swings are on subject pronouns, and the sign follows the kind of
verb the subject takes next, which the program cannot see, so it uses two
proxies: the pronoun itself and the word just before it.

- you / we / I / they (verbs that are modal or not 3rd-person singular, e.g.
  "you can", "we need", "they will") go negative. They go most negative when
  the pronoun opens a dependent clause ("that you", "if we", "so they").
- it / he / she / this / which / who / that (typically a 3rd-person singular
  subject of "is", "has", "means") go positive when they start a sentence or
  follow a comma, and go slightly negative after a clause opener.
- Everything else gets the resting value.

It reads only the current token and the one before it.
"""

READS = ()

PERSONAL = {"you", "we", "i", "they"}
THIRD_SING = {"it", "he", "she", "this", "which", "who", "that"}
CLAUSE_OPENERS = {
    "that", "if", "when", "so", "where", "which", "who", "how", "because",
    "once", "as", "while", "until", "since", "unless", "whether", "why",
    "what", "and", "but", "or", "though", "after", "before", "then", "for",
}
BOUNDARY = {".", "!", "?", "\n", ":", ";"}
REST = -0.1


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.token_strings) > 1 and (
        prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    before = prefix.token_strings[-2].strip().lower() if same_doc else "."
    if word in PERSONAL:
        value = -2.6 if before in CLAUSE_OPENERS else -1.2
    elif word in THIRD_SING:
        if before in BOUNDARY:
            value = 1.0
        elif before == ",":
            value = 0.6
        elif before in CLAUSE_OPENERS:
            value = -0.35
        else:
            value = -0.13
    else:
        value = REST
    return carry, value

"""Sentence-end detector for layers.15.mlp.down_proj component 2791.

The component is strongly negative on the full stop (or ? ! 。 ？ ！) that closes an ordinary
sentence, and near zero on every other token. Refinements:
- a sentence end after a decimal number ("3.5", "in 1990."), an initial ("J.") or a short
  capitalised or all-caps abbreviation ("Mr.", "Co.", "U.S.") is weak: these are not real ends;
- a sentence that is still short (under 8 tokens) gives a weaker value than a long one;
- every other token (words, spaces, digits, commas) predicts 0.
"""

READS = ()

ENDS = {".", "?", "!", "。", "？", "！"}
SHORT_SENTENCE = 8  # tokens since the last sentence end
LONG_VALUE = -2.75  # sentence end after a long-enough sentence
SHORT_VALUE = -1.3  # sentence end after a short one
WEAK_VALUE = -0.6  # decimal point, initial or abbreviation


def is_weak_word(word):
    """The previous token is a digit, or a capitalised / all-caps abbreviation of <= 3 letters."""
    word = word.strip()
    if word[-1:].isdigit():
        return True
    return word.isupper() or (word[:1].isupper() and len(word) <= 3)


def step(carry, prefix, upstream):
    # carry: tokens since the last sentence end in this document (None at a row's start)
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    since = 0 if carry is None or new_doc else carry
    if prefix.token_strings[-1] not in ENDS:
        return since + 1, 0.0
    prev = "" if new_doc else prefix.token_strings[-2]
    if is_weak_word(prev):
        value = WEAK_VALUE
    elif since < SHORT_SENTENCE:
        value = SHORT_VALUE
    else:
        value = LONG_VALUE
    return 0, value

"""Clause-joining words in the residual stream's MLP output at layer 15.

The component reads disjunctions and connectives as they begin a new clause or
alternative. A standalone "or" (or its translation: или, oder, ou, o, 或, nor, sondern)
gives the strongest activation, about 4 after a comma and about 2.3 otherwise.
Other connectives (and, и, und, y, but, as, which, who, than, yet, while, even, not)
give a moderate value after a comma (1.5) and a weak one otherwise (0.4). Everything
else is 0. Words inside another word (a sub-word token such as the "or" in "Element|or")
do not count, and a comma only counts when it is in the same document.
"""
from collections.abc import Mapping

READS = ()

ALTERNATIVES = {"or", "или", "oder", "o", "ou", "nor", "либо", "或", "sondern", "rather"}
CONNECTIVES = {"and", "и", "und", "y", "but", "as", "which", "who", "than", "yet", "while", "even", "not"}
COMMAS = {",", "，"}


def step(carry, prefix, upstream: Mapping):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    # A word counts when it starts a token after a space (or is a non-Latin word, or opens the text).
    standalone = raw[:1] == " " or not raw[:1].isascii() or prefix.position == 0
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    after_comma = same_doc and prefix.token_strings[-2].strip() in COMMAS
    if not standalone:
        return carry, 0.0
    if word in ALTERNATIVES:
        return carry, (4.0 if after_comma else 2.3)
    if word in CONNECTIVES:
        return carry, (1.5 if after_comma else 0.4)
    return carry, 0.0

"""Joiner tokens: a component that fires on the marks that bind a modifier or a possessive
to the word it belongs to.

Strongest on:
- hyphens inside compounds ("Michelin-starred", "lipid-modifying", "Forschungs-und",
  "command-line"), bare or fused with the next piece ("-based", "-s");
- attributive particles 的 の 之 의 (Chinese, Japanese, Korean "of"-words);
- the possessive 's and ’s.
Weaker on underscores in identifiers, closing brackets, slashes and newlines.
Almost everything else sits near zero. Each value is the mean activation of its class on
training text, so the program predicts the class average and nothing finer.
"""

import re

READS = ()

DASHES = re.compile(r"[-‐‑–—]")
PARTICLES = frozenset("的の之의")
POSSESSIVES = frozenset(["'s", "’s"])


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in PARTICLES:
        value = 3.3
    elif tok in POSSESSIVES:
        value = 2.4
    elif DASHES.search(tok):
        if tok.startswith(" "):
            value = 0.4  # a dash set off by a space is not a compound joiner
        elif DASHES.fullmatch(tok):
            value = 2.3  # a bare dash between two word pieces
        else:
            value = 1.8  # a dash fused with the piece after it, e.g. "-based"
    elif "_" in tok:
        value = 0.5
    elif tok in (")", "/"):
        value = 0.9
    elif tok == "\n":
        value = 0.5
    else:
        value = 0.1
    return carry, value
